INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Near FM provides podcasting support to Ireland’s community groups', 'podcasting-support-for-community-sector', '<p>Near FM has officially launched a professional podcasting service for groups in the community sector. It has been providing the service since 2016 and has won awards, but is only now getting around to publicising it.</p>
<p>Many more community groups might take an interest in podcasting knowing that someone else is looking after the technical aspects, knowing that basic training is available and that the price is right.</p>
<p>That is what Near FM are offering and Changing Ireland is trying it out; we have engaged them on the technical side to help put out podcast interviews we conduct ourselves.</p>
<p>“We promise better then commercial rates,” said station manager Ciaran Murray.</p>
<p>“Ideally, people talk to us before they begin recording. If an organisation is clear on what it wants, we can have podcasts ready in a few weeks.</p>
<p>“Our studios are in Dublin however we might be able to arrange a more local recording, using our network of community radio stations around the country,” he said.</p>
<p>To date Near FM has worked with local and national organisations including The Wheel, The Irish Foster Care Association, the Prevention and Early Intervention Network, Tallaght Drugs and Alcohol Taskforce, Aoibhneas and AONTAS.</p>
<p>They produce an ongoing series of podcasts titled ‘Stories From Foster Care’ with The Irish Foster Care Association.</p>
<p>“People who have been through fostering tell their story,” said Ciaran. “They reflect on that time they were in foster care, and how important it was for them, and how the experience was for them.”</p>
<p>“All podcasts are hosted on Nearcast and populated on all major podcast platforms including Spotify and Apple,” said Ciaran.</p>
<p>For instance, Sadie Harpur, author of The Hidden World of a Foster-Girl, told about her experience undergoing multiple moves in care, her relationships with her twin sister Kizzy and her birth- and foster-families, and who brought stability to her life.</p>
<p>You can listen to it here: <a href="https://nearcast.ie/stories-from-foster-care-sadie-harpur/">https://nearcast.ie/stories-from-foster-care-sadie-harpur/</a></p>
<p>This particular podcast won the station Gold for Best Podcast at last year’s Craol Community Radio Awards.</p>
<p>To find out more, contact Ciaran or Paul at Near FM.</p>
<p>E: ciaran@near.ie, paul@near.ie<br />
T: 01-8671190.<br />
W: <a href="https://nearcast.ie/">https://nearcast.ie/</a></p>', 'Near FM has officially launched a professional podcasting service for groups in the community sector. It has been providing the service since 2016 and has won awards, but is only now getting around to publicising it. Many more community groups might take an interest in podcasting knowing that someone else is looking after the technical', 'https://changingireland.ie/wp-content/uploads/2024/11/Near-FM-recording-1.png', '', '[{"slug":"enterprise","title":"Enterprise"}]', '[]', '', 254670, 1, '2024-11-29T11:45:58Z', '2024-11-29T01:40:20Z', '2024-11-29T11:45:58Z')
