<p>&nbsp;</p>', '€7 million in funding is to be provided to community groups under the Department of Rural and Community Development Local Enhancement Programme 2025.', 'https://changingireland.ie/wp-content/uploads/2023/03/CCVESS.jpg', '', '[{"slug":"funding-programmes","title":"Funding Programmes"}]', '[{"slug":"community-development","title":"community development"},{"slug":"community-groups","title":"community groups"},{"slug":"department-of-rural-and-community-development-drcd","title":"Department of Rural and Community Development (DRCD)"},{"slug":"funding","title":"funding"},{"slug":"local-community-development-committee-lcdc","title":"Local Community Development Committee LCDC"},{"slug":"local-enhancement-programme-2025","title":"Local Enhancement Programme 2025"},{"slug":"marginalised-communities","title":"marginalised communities"},{"slug":"mens-sheds","title":"Men''s Sheds"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"minister-joe-obrien","title":"Minister Joe O''Brien"},{"slug":"our-rural-future","title":"Our Rural Future"},{"slug":"rural-development","title":"rural development"},{"slug":"womens-sheds","title":"women''s sheds"}]', '', 254664, 1, '2024-11-08T12:43:43Z', '2024-11-08T12:43:43Z', '2024-11-08T12:43:43Z')
