INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Increased funding for 400 community organisations', 'increased-funding-for-400-community-organisations', '<p><span>Over 400 community organisations nationwide are set to benefit from the announcement, made by Minister for Community Development, Integration and Charities, Joe O’Brien today.</span></p>
<p><span>The CSP aims to provide employment opportunities and local services to disadvantaged communities. </span></p>
<p><span>The revised funding rates to be applied from January 1 2025 will see an increase of €1,850 in the annual contribution per full-time equivalent post to organisations categorised as having a high funding need.</span></p>
<p><span>It will also see a €1,755 increase in the annual contribution per full-time equivalent post for CSP organisations categorised as having a medium funding need.</span></p>
<p><span>No change is proposed for the small number of organisations in the low funding category, these are organisations identified as having the strongest earning potential and operating in less disadvantaged areas.</span></p>
<p><span>These increases will assist organisations to meet higher labour costs from 2025 onwards.</span></p>
<p><span>Minister O’Brien said: “I am very conscious of the increased costs being faced by organisations supported under the Community Services Programme and the increases being announced today will ensure the continued sustainability of the supported organisations.</span></p>
<p><span>“The increases provide higher levels of support to organisations with limited earning potential, operating in areas of disadvantage and employing individuals from the prescribed programme target groups.”</span></p>', 'An additional €3 million funding has been allocated to support community services organisations from January 2025 under the Community Services Programme (CSP).', 'https://changingireland.ie/wp-content/uploads/2024/07/451017628_885672020263785_2541608581007279886_n-e1730766349793.jpg', '', '[{"slug":"funding-programmes","title":"Funding Programmes"}]', '[{"slug":"community-development","title":"community development"},{"slug":"community-services-programme-csp","title":"Community Services Programme CSP"},{"slug":"department-of-rural-and-community-development-drcd","title":"Department of Rural and Community Development (DRCD)"},{"slug":"employment","title":"employment"},{"slug":"funding","title":"funding"},{"slug":"minister-joe-obrien","title":"Minister Joe O''Brien"}]', '', 254655, 1, '2024-11-05T13:53:02Z', '2024-11-05T13:53:02Z', '2024-11-05T13:53:02Z')
