INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Staggering output and vital community work highlighted', 'staggering-output-and-vital-community-work-highlighted', '<p>At the Welcoming New Communities conference held recently in Dublin Castle, Bairbre Nic Aongusa, assistant secretary at the Department of Rural and Community Development, said it was important &#8220;to pause and to reflect on the work we do&#8221;.</p>
<div><iframe title="Bairbre Nic Aongusa thanks community workers for integration during &quot;turbulent&quot; times" width="696" height="392" src="https://www.youtube.com/embed/0Lfjiuldhik?start=43&amp;feature=oembed" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div>
<p>She said that while it is far from plain sailing she is confident community organisations, with Department support, will continue to rise to the<br />
challenges: &#8220;All of our funding and all of our programmes would amount to nothing without the commitment and the support of those of you who are at the frontline. The work of the community and voluntary sector &#8211; local development companies, volunteer centres, community groups and local networks &#8211; is so vital. And you have done staggering work over recent years in developing and delivering programmes to your communities,&#8221; she added.</p>
<p>&#8220;To say that the context that you operate in has been changeable would be a total understatement. In the past four years as we know we have all had to respond to monumental challenges starting with the pandemic, followed by the outbreak of the terrible conflict in Ukraine, and then the unprecedented numbers of new arrivals into our communities seeking sanctuary and support here in Ireland.</p>
<p>&#8220;To your credit, you as a sector have risen to all of these challenges and continue to deal with the challenges on a daily basis. Your adaptability, understanding and empathy &#8211; and very importantly your reliability as partners with us &#8211; has enabled our department to be as flexible as possible in overseeing the implementation of a variety of our funding supports and schemes.</p>
<p>&#8220;When we needed to pivot to address a new challenge you pivoted with us and for that we&#8217;re really grateful. And really do appreciate the terrific work you do,&#8221; she said.</p>
<p>The Department of Rural and Community Development&#8217;s mission is to support vibrant inclusive and sustainable communities all over Ireland in both urban areas and rural areas.</p>
<p>Bairbre said, &#8220;I think everybody will agree that one of the very biggest challenges that our communities face in Ireland today is how to welcome our new arrivals.</p>
<p>&#8220;I&#8217;m sure there are many people who have arrived in Ireland in the last couple of years who would acknowledge that the work you do helped them to start integrating into their new home.</p>
<p>&#8220;There&#8217;s no doubt that the work that you do has a profound impact on the lives of many.</p>
<p>&#8220;Your expertise and passion and commitment has helped to steer this country&#8217;s integration efforts through some very turbulent waters and we&#8217;re not saying it’s plain sailing yet by any means. But I think the commitment and the track record is assurance enough that together we can overcome the challenges,&#8221; she concluded.</p>', 'Community development workers and volunteers have been thanked for their “vital” work and their “staggering” output amidst unprecedented challenges.', 'https://changingireland.ie/wp-content/uploads/2024/10/WNC-946-Photo-by-Allen-Meagher-scaled.jpeg', '', '[{"slug":"activism-volunteering","title":"Activism & Volunteering"}]', '[{"slug":"community-and-voluntary-organisations","title":"community and voluntary organisations"},{"slug":"community-and-voluntary-sector","title":"Community and Voluntary sector"},{"slug":"community-development","title":"community development"},{"slug":"department-of-rural-and-community-development-drcd","title":"Department of Rural and Community Development (DRCD)"},{"slug":"integration","title":"integration"},{"slug":"rural-development","title":"rural development"},{"slug":"volunteering","title":"volunteering"},{"slug":"volunteers","title":"volunteers"}]', '', 254531, 1, '2024-10-21T10:46:44Z', '2024-11-05T00:38:29Z', '2024-10-21T10:46:44Z')
