INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Clann Credo has loaned €215 million to community groups since 1996', 'clann-credo-has-loaned-e215-million-to-community-groups-since-1996', '<p>As the largest social finance provider in Ireland, Clann Credo has a current loan book of over €50.3 million, providing capital to community and voluntary groups around the country.</p>
<p>Working like a social bank, Clann Credo has supported more than 1,500 organisations in the community, providing lending that focuses on the social impact potential of a project.</p>
<p>Clann Credo CEO Mary Lawlor said, “Clann Credo is strategically positioned to respond effectively to evolving community needs and ambition. The feedback from the 250 delegates at our conference signals an increase in community ambition throughout Ireland which gives us confidence to scale our work and reach more communities who share our mission for positive social change.”</p>
<p>Over 250 community and voluntary organisations from around Ireland attended the conference, held at Croke Park on September 13.</p>
<p>According to the latest Clann Credo Impact Report, 65% of Clann Credo’s social finance lending in 2023 reached communities with a below-average score on the Pobal Deprivation Index.</p>
<p>Specifically, Clann Credo demonstrated an increase in their lending to communities classified as disadvantaged (11%) or extremely<br />
disadvantaged (4%) during that year. This level of lending in underserved communities demonstrates the need for social finance in Ireland, now and into the future.</p>
<p>Clann Credo finance supports sporting clubs (38.9%), community playgrounds, community centres and facilities in the community (16.7%)<br />
as well as disability projects (9.9%), enterprise centres (8.4%), and social sheltered housing (6.6%) among other projects.</p>
<p>It also aims to support environmental and climate action initiatives in communities. For instance, its support helped to transform a disused,<br />
overgrown site at the heart of Carlow Town into an urban variant of the allotment idea called An Gairdín Beo.</p>
<p>Speaking at the conference, Minister for Finance Jack Chambers said, “It’s clear Clann Credo are making a real social impact on the ground around the country, through their support of community, sporting and voluntary groups. I have seen this first hand. The level of social finance required in Ireland over the last number of years demonstrates the need for this type of finance, and reflects the huge ambition of local community groups.”</p>', 'Irish social finance organisation Clann Credo has provided over €215 million in finance to community and voluntary groups, sports clubs, climate action initiatives, social enterprises as well as social housing in Ireland since 1996.', 'https://changingireland.ie/wp-content/uploads/2024/10/Clann-Credo-conference-2024-3-scaled.jpg', '', '[{"slug":"community-finance","title":"Community Finance"}]', '[{"slug":"clann-credo","title":"Clann Credo"},{"slug":"community-and-voluntary-sector","title":"Community and Voluntary sector"},{"slug":"community-finance","title":"community finance"},{"slug":"community-organisations","title":"Community organisations"},{"slug":"finance","title":"finance"},{"slug":"voluntary-organisations","title":"voluntary organisations"}]', '', 254499, 1, '2024-10-14T11:55:39Z', '2024-10-14T11:55:39Z', '2024-10-14T11:55:39Z')
