INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Tús team in Meath develop prototype ‘screenhouse’ made from old Covid screens', 'tus-team-in-meath-develop-prototype-screenhouse-made-from-old-covid-screens', '<p><span>“We were getting rid of the screens </span><span>on the desks in Meath Partnership,” </span><span>recalled Tommy Melia, Tús </span><span>supervisor. </span><span>“They’re made of perspex </span><span>and I thought they were too good to </span><span>throw out.” </span></p>
<p><span>Then he and his crew got a </span><span>brainwave &#8211; screenhouses in place of </span><span>greenhouses.  </span></p>
<p><span>The construction process is </span><span>straightforward, as Tommy explained. </span><span>“We built the greenhouse frame first, </span><span>and then just used screws and washers </span><span>and screwed the screens in. The door </span><span>is wide enough for a wheelbarrow and </span><span>I’m six-foot-four and I can walk in no </span><span>problem. It’s a prototype to see could </span><span>we do it and it works. A lot of credit </span><span>has to go to the crew,” he revealed. </span></p>
<p><span>The team have since helped </span><span>to build community gardens in </span><span>accommodation centres in Co </span><span>Meath. </span></p>
<p>Tús is a community work placement scheme providing short-term working opportunities for unemployed people. All the work carried out by<br />
participants on the Tús is community-based.</p>
<p>If you want the blueprint to build your own screenhouse, contact Meath Partnership or, if you&#8217;re in the vicinity and want to have old Covid screens recycled by them, email: marjan.boers@meathpartnership.ie</p>
<p>For more, see www.meathpartnership.ie</p>', 'In Co Meath, the Tús community crew took the old Covid screens that once divided us and used them to make a greenhouse (screenhouse) that can be used in community gardens.', 'https://changingireland.ie/wp-content/uploads/2024/10/Iss-86-Meath-Covid-screens-reused-to-make-screenhouse-2.jpg', '', '[{"slug":"enterprise","title":"Enterprise"}]', '[{"slug":"covid-19","title":"#COVID-19"},{"slug":"circular-economy","title":"circular economy"},{"slug":"community-development","title":"community development"},{"slug":"community-gardens","title":"community gardens"},{"slug":"meath","title":"Meath"},{"slug":"meath-partnership","title":"Meath Partnership"},{"slug":"recycling","title":"recycling"},{"slug":"social-enterprise","title":"social enterprise"},{"slug":"tus-community-employment-scheme","title":"Tús community employment scheme"}]', '', 254492, 1, '2024-10-10T09:26:13Z', '2024-10-09T11:42:49Z', '2024-10-10T09:26:13Z')
