INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Clare leads out with country’s first Queer Shed', 'clare-leads-out-with-countrys-first-queer-shed', '<div>
<div>We&#8217;ve had Men&#8217;s Sheds and Women&#8217;s Sheds and now the first Queer Shed is up and running &#8211; in rural West Clare.</div>
</div>
<div>
<div></div>
<div>Queer Sheds is a new initiative aiming to address the social isolation experienced by LGBT+ people in people in rural Ireland. Inspired by Men&#8217;s Sheds, which have had a huge impact in tackling isolation, a social enterprise called Common Knowledge has initiated a six- month pilot queer shed in Kilfenora, Co Clare.</div>
<div></div>
<div>With the support of Clare County Council, Clare&#8217;s Queer Shed aims to raise visibility, build a queer community and measure the need for this kind of space.</div>
</div>
<div></div>
<div>
<figure aria-describedby="caption-attachment-254447"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2024/09/Clares-Queer-Shed-members-now-know-how-to-build-a-clay-pizza-oven.jpg" alt="" width="1080" height="1080" srcset="https://changingireland.ie/wp-content/uploads/2024/09/Clares-Queer-Shed-members-now-know-how-to-build-a-clay-pizza-oven.jpg 1080w, https://changingireland.ie/wp-content/uploads/2024/09/Clares-Queer-Shed-members-now-know-how-to-build-a-clay-pizza-oven-300x300.jpg 300w, https://changingireland.ie/wp-content/uploads/2024/09/Clares-Queer-Shed-members-now-know-how-to-build-a-clay-pizza-oven-1024x1024.jpg 1024w, https://changingireland.ie/wp-content/uploads/2024/09/Clares-Queer-Shed-members-now-know-how-to-build-a-clay-pizza-oven-150x150.jpg 150w, https://changingireland.ie/wp-content/uploads/2024/09/Clares-Queer-Shed-members-now-know-how-to-build-a-clay-pizza-oven-768x768.jpg 768w, https://changingireland.ie/wp-content/uploads/2024/09/Clares-Queer-Shed-members-now-know-how-to-build-a-clay-pizza-oven-440x440.jpg 440w, https://changingireland.ie/wp-content/uploads/2024/09/Clares-Queer-Shed-members-now-know-how-to-build-a-clay-pizza-oven-24x24.jpg 24w, https://changingireland.ie/wp-content/uploads/2024/09/Clares-Queer-Shed-members-now-know-how-to-build-a-clay-pizza-oven-48x48.jpg 48w, https://changingireland.ie/wp-content/uploads/2024/09/Clares-Queer-Shed-members-now-know-how-to-build-a-clay-pizza-oven-96x96.jpg 96w" sizes="(max-width: 1080px) 100vw, 1080px" /><figcaption> • <em>Clare&#8217;s Queer Shed members now know how to build a clay pizza oven</em></figcaption></figure>
</div>
<div></div>
<div>
<div>In Kilfenora, members have access to land, facilities and tools. &#8220;We are a diverse group with representation from across the LGBTQ+ spectrum and are currently meeting at least once per month,&#8221; it says.</div>
<div></div>
<div>The shed held its first skill share session in June when shed members learned how to build a clay oven for cooking pizza.</div>
<div></div>
<div>In July it held a three-day festival called  &#8216;Faoin Tuath&#8217; featuring live music, DJs, talks, performances and skill-sharing workshops.</div>
<div></div>
<div>There are over 400 Men&#8217;s Sheds in the country. The idea originated in Australia and has been very successful in Ireland. It has inspired the opening of a number of women&#8217;s sheds around the country.</div>
<div></div>
<div>If you are interested in joining Clare&#8217;s Queer Shed, or having a Queer Shed in your area, visit: <b><i><a href="https://www.queersheds.org/" target="_blank" rel="noopener noreferrer">https://www.queersheds.org/</a></i></b></div>
</div>', '• Idea modelled on men’s sheds which have track record in tackling isolation •', 'https://changingireland.ie/wp-content/uploads/2024/09/Clares-Queer-Shed-6.jpeg', '', '[{"slug":"community","title":"Community"}]', '[{"slug":"clare-county-council","title":"Clare County Council"},{"slug":"co-clare","title":"Co Clare"},{"slug":"community-building","title":"community building"},{"slug":"community-development","title":"community development"},{"slug":"kilfenora","title":"Kilfenora"},{"slug":"lgbt","title":"LGBT"},{"slug":"mens-sheds","title":"Men''s Sheds"},{"slug":"queer-community","title":"queer community"},{"slug":"queer-sheds","title":"Queer Sheds"},{"slug":"rural-development","title":"rural development"},{"slug":"rural-ireland","title":"rural ireland"},{"slug":"rural-isolation","title":"rural isolation"},{"slug":"social-isolation","title":"social isolation"},{"slug":"womens-sheds","title":"women''s sheds"}]', '', 254445, 1, '2024-09-16T13:36:16Z', '2024-09-16T13:37:07Z', '2024-09-16T13:36:16Z')
