INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('48 new vehicles to be provided for essential services', '48-new-vehicles-to-be-provided-for-essential-services', '<p><span>Vehicles will also be provided to support community first responders and search and rescue services.</span></p>
<p><span>The funding, announced today, is being allocated under the 2024 CLÁR programme.</span></p>
<p><span>It represents the highest number of vehicles ever funded through the programme, bringing the number delivered under this measure to over 200 since it was introduced in 2018.</span></p>
<p><span>Some of the projects being supported include:</span></p>
<ul>
<li><span>Dunmanway Family Resource Centre in Cork – €52,000 for a modified mobility vehicle</span></li>
</ul>
<ul>
<li><span>Acquired Brain Injury Ireland, Co Kerry &#8211; €59,880 for a vehicle to transport brain injury survivors</span></li>
</ul>
<ul>
<li><span>Order of Malta, Kilkenny &#8211; €72,000 for the purchase of an ambulance</span></li>
</ul>
<ul>
<li><span>Offaly Healthy Homes &#8211; €33,750 for a vehicle to support their meals on wheels&#8217; service.</span></li>
</ul>
<p><span>Minister for Rural and Community Development, Heather Humphreys said: &#8220;I am very pleased to be supporting these vital services in our most remote rural communities right across the country. Each of the recipients of funding today plays a vital role in providing essential services to those who are most in need in our communities, be it from a mobility aspect or through the provision of meals on wheels services.</span></p>
<p><span>“The supports provided by our First Responders and our Search and Rescue teams are of immense importance and I am delighted to be in a position to support these very worthy community groups today. We owe a great deal to these organisations and to all the individuals who volunteer with them.&#8221;</span></p>
<p><span>Details of all the successful projects can be found </span><a href="https://www.gov.ie/pdf/?file=https://assets.gov.ie/304993/aca79ac8-6455-4f0a-a739-24bdd67ab854.pdf"><span>here.</span></a></p>', 'More than €2.1 million has been allocated to provide 48 vehicles for a number of services including cancer care, transport for people with mobility issues, and to deliver meals on wheels to the elderly and other vulnerable people.', 'https://changingireland.ie/wp-content/uploads/2024/09/Minister-Humphreys-Meals-on-Wheels-scaled.jpg', '', '[{"slug":"funding-programmes","title":"Funding Programmes"}]', '[{"slug":"cancer-care","title":"cancer care"},{"slug":"clar-programme","title":"CLÁR Programme"},{"slug":"community-development","title":"community development"},{"slug":"community-vehicles","title":"community vehicles"},{"slug":"department-of-rural-and-community-development-drcd","title":"Department of Rural and Community Development (DRCD)"},{"slug":"first-responders","title":"first responders"},{"slug":"funding","title":"funding"},{"slug":"meals-on-wheels","title":"meals on wheels"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"mobility","title":"mobility"},{"slug":"rural-development","title":"rural development"},{"slug":"transport","title":"transport"}]', '', 254440, 1, '2024-09-13T10:27:03Z', '2024-09-13T10:27:36Z', '2024-09-13T10:27:03Z')
