INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('€2.6m to support Town Centre First Projects', 'e2-6m-to-support-town-centre-first-projects', '<p><span>A total of 53 projects will be supported with up to €50,000 of funding provided per project.</span></p>
<p><span>The funding will support pre-development works for projects and support costs including detailed design, planning, procurement, professional fees, assessments and other development costs.</span></p>
<p><span>The planned projects include the enhancement of a town centre park in Tullow, Co. Carlow, to provide a modern play area with accessible natural paths and family-friendly areas, as well as the development of a visitor hub for Mount Errigal in Dunlewey, Co Donegal.</span></p>
<p><span>In Co Cork, pre-development planning for a new town centre plaza in Kinsale, and the development of a community hub in Ladysbridge are among the successful projects.</span></p>
<p><span>The funding scheme will also support the preparation of a programme of works to improve and upgrade the shopfronts on the Main Square in Abbeyfeale, Co Limerick, and works to redevelop the derelict Bridewell Building in Carrickmacross, Co Monaghan into a community hub.</span></p>
<p><span>Further information on Town Centre First can be found </span><a href="https://www.gov.ie/en/publication/473d3-town-centre-first-policy/#town-centre-first-suite-of-supports-2024"><span>here</span></a><span> on gov.ie.</span></p>', 'A funding boost of €2.6 million has been announced by the Department of Rural and Community Development to support a wide range of Town Centre First projects across Ireland.', 'https://changingireland.ie/wp-content/uploads/2024/09/Kinsale.jpg', '', '[{"slug":"funding","title":"Funding"}]', '[{"slug":"co-carlow","title":"Co Carlow"},{"slug":"co-cork","title":"Co Cork"},{"slug":"co-donegal","title":"Co Donegal"},{"slug":"co-monaghan","title":"Co Monaghan"},{"slug":"community","title":"Community"},{"slug":"community-development","title":"community development"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"funding","title":"funding"},{"slug":"kinsale","title":"Kinsale"},{"slug":"rural-development","title":"rural development"},{"slug":"town-centre-first","title":"Town Centre First"}]', '', 254435, 1, '2024-09-03T10:05:55Z', '2024-09-03T10:05:55Z', '2024-09-03T10:05:55Z')
