INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Minister reminds community organisations of funding deadline', 'minister-reminds-community-organisations-of-funding-deadline', '<p>Community groups are being encouraged to get their applications for the Community Centre Investment Fund finalised as soon as possible as the deadline approaches this week.</p>
<p>Minister for Rural and Community Development, Heather Humphreys, last week extended the closing date for the Community Centre Investment Fund to 3pm on Thursday September 5.</p>
<p>Under the Community Centres Investment Fund 2024, community organisations will be supported with grants of between €10,000 &#8211; €100,000 to develop and enhance their existing community facilities. The original closing date was August 29.</p>
<p>Minister Humphreys said: &#8220;While most groups now have everything in place, I know that there are still some who are finalising different aspects of their application. I&#8217;m very aware that these applications are being completed by local volunteers and committees who have lots of other demands on their time. I want to give local groups every chance to get their applications finalised and submitted.</p>
<p>&#8220;There is huge interest from local groups in towns, villages and parishes across the country in upgrading and refurbishing their local community centre. This one week extension will give everybody the chance to put their best foot forward and get their application submitted well ahead of the new deadline.&#8221;</p>
<p>There have been a number of online information events to assist potential applicants. Recordings of these events together with a range of information supports and access to the online portal can be found at the Department of Rural &amp; Community Development website <a href="https://www.gov.ie/en/service/fec91-community-centres-investment-fund/" target="_blank" rel="noopener noreferrer">here.</a> Groups can also submit any queries to <a href="mailto:ccif@pobal.ie" rel="noreferrer">ccif@pobal.ie</a>.</p>', 'The closing date for applications to the Community Centre Investment Fund has been extended to 3pm this Thursday, September 5', 'https://changingireland.ie/wp-content/uploads/2024/09/Minister-Humphreys-scaled.jpg', '', '[{"slug":"funding-programmes","title":"Funding Programmes"}]', '[{"slug":"community","title":"Community"},{"slug":"community-centre-investment-fund-ccif","title":"Community Centre Investment Fund (CCIF)"},{"slug":"community-centres","title":"Community centres"},{"slug":"community-development","title":"community development"},{"slug":"community-facilities","title":"community facilities"},{"slug":"community-organisations","title":"Community organisations"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"funding","title":"funding"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"rural-development","title":"rural development"}]', '', 254429, 1, '2024-09-02T10:53:39Z', '2024-09-02T10:53:39Z', '2024-09-02T10:53:39Z')
