INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('What makes social enterprises unique?', 'what-makes-social-enterprises-unique', '<p>Speaking at a TUS-organised seminar in Limerick recently, Dr Mary O’Shaughnessy, head of UCC&#8217;s Department of Food Business and Development, outlined why social enterprises are unique.</p>
<p>They emerge to fulfill local needs that are not met otherwise;<br />
They have a strong local focus, often driven by a sense of community and anchored in community relations;<br />
They combine a wide range of resources and networks.</p>
<p>She said rural social enterprises strengthen trust, solidarity and community cohesion: “However, there is sometimes a gap between policy discourse and actual support needed.”</p>
<p>Drawing on research she and colleagues have been involved in, she highlighted the wide-ranging impact of social enterprises. This includes empowering vulnerable social groups, giving them a voice, increasing their independence and promoting capacity building.<br />
Social enterprises help society meet UN Sustainable Development Goals (SDGs) such as poverty reduction and food security (goals one and two).</p>
<p>They also help to achieve:</p>
<p>Sustainable and inclusive economic growth and decent work;<br />
Social, political and economic inclusion of vulnerable groups;<br />
and contribute to the construction of sustainable communities.</p>
<p>These latter three contribute to achieving SDGs 8, 10 and 11 respectively.</p>
<p>On the flip side, Mary said, “If it’s not done well it can erode goodwill and destroy the potential for social impact in a place.” She also pointed out, “Unrealistic expectations sometimes arise where supporters/backers expect the social innovators to solve all problems.”</p>
<p>Mary has co-authored a paper about rural social enterprises across Europe, available to read <a href="https://journals.sagepub.com/doi/full/10.1177/0269094220907024">here.</a></p>
<p>For more, see https://changingireland.ie/learning-shared-from-erasmus-community-enterprise-project</p>', 'A strong local focus, fulfilling local needs, and driven by a sense of community are key elements of social enterprises, according to Dr Mary O’Shaughnessy', '', '', '[{"slug":"enterprise","title":"Enterprise"}]', '[{"slug":"dr-mary-oshaughnessy","title":"Dr Mary O''Shaughnessy"},{"slug":"social-enterprise","title":"social enterprise"},{"slug":"tus-technological-university-of-the-shannon","title":"TUS Technological University of the Shannon"},{"slug":"ucc-university-college-cork","title":"UCC University College Cork"},{"slug":"un-sustainable-development-goals","title":"UN Sustainable Development Goals"}]', '', 254398, 1, '2024-07-31T11:56:34Z', '2024-07-31T11:56:34Z', '2024-07-31T11:56:34Z')
