INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Learning shared from ERASMUS+ community enterprise project', 'learning-shared-from-erasmus-community-enterprise-project', '<p>Learning from across Europe about community enterprises, a subset of social enterprises, has been shared online for interested parties, following the completion of an Erasmus+ sponsored project called ComEnt.</p>
<p>Partners in six countries collaborated over two years to produce reports, case- studies (including 19 videos), learning materials and policy recommendations.</p>
<p>A course was held as part of the project and students who participated between September and December of last year received a Certificate in Community Enterprise (NFQ Level 8). The course aimed at enabling community workers, social innovators and mentors to better support social enterprises.</p>
<p>Five reports were produced, and the Irish report looks at social enterprise in practice, case-studies, and policy recommendations. There are also reports from Austria (in English), Bulgaria, Italy and Romania.</p>
<p>The Technological University of the Shannon (TUS) was the lead partner for the ComEnt project.</p>
<p>Click<a href="https://www.comenterasmus.eu/results/"> here</a> to access the learning.</p>
<p>For more, see https://changingireland.ie/what-makes-social-enterprises-unique/</p>', '– Includes 19 videos, five country reports, all learning materials', 'https://changingireland.ie/wp-content/uploads/2024/07/Screenshot_20240730_141145_Gmail.jpg', '', '[{"slug":"enterprise","title":"Enterprise"}]', '[{"slug":"coment","title":"ComEnt"},{"slug":"community-enterprise","title":"Community Enterprise"},{"slug":"erasmus","title":"Erasmus+"},{"slug":"social-enterprise","title":"social enterprise"},{"slug":"tus-technological-university-of-the-shannon","title":"TUS Technological University of the Shannon"}]', '', 254400, 1, '2024-07-31T11:47:27Z', '2024-07-31T11:47:27Z', '2024-07-31T11:47:27Z')
